    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return out
    bottom = max(r for r, c in pts)

    # Complete each vertical run between consecutive original marks.
    for c in range(w):
        rows = sorted(r for r, cc in pts if cc == c)
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # The horizontal rows are line segments only when there is a contiguous
    # foreground run, or the row is the lowest marked boundary row.
    for r in range(h):
        cols = sorted(c for rr, c in pts if rr == r)
        if (any(b == a + 1 for a, b in zip(cols, cols[1:]))
                or (r == bottom and len(cols) >= 2)):
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
