        cols = sorted(c for rr, c in marks if rr == r)
        has_run = any(b == a + 1 for a, b in zip(cols, cols[1:]))
        if has_run or (r == bottom and len(cols) >= 2):
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
